/// What clipboard sync (§3.5 CLIPBOARD) leaves on the Mac it was copied on.
/// Password managers mark what they put on the clipboard, following
/// nspasteboard.org: a concealed item (a password), a transient one (to be
/// pasted once and gone), or one an app generated rather than the person
/// copied. Neither app sends one of these to the other Mac, in either
/// direction (§13).
public enum ClipboardSync {
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// Whether a pasteboard holding `types` (its type identifiers) may be sent.
    public static func mayShare(types: [String]) -> Bool {
        privateTypes.isDisjoint(with: types)
    }
}
